head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#faf6e9" value="#faf6e9"/><Variable name="page.text" description="Text color" type="color" default="#48404a" value="#48404a"/><Variable name="theme.accent" description="Accent color" type="color" default="#9d4569" value="#9d4569"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Caveat', Georgia, serif;--body:Trebuchet MS, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{margin:0;background:#faf6e9;color:#48404a;font-family:"Trebuchet MS",sans-serif;background-image:radial-gradient(#b9aa9028 .8px,transparent .8px);background-size:8px 8px}.mess-nav{padding:27px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px dashed #b9aa90}.mess-nav .brand{font:italic bold 25px 'Caveat', Georgia,serif;letter-spacing:-1px;text-decoration:none}.mess-nav .brand span{color:#9d4569;font-size:32px}.mess-nav nav{display:flex;gap:25px;font-size:11px}.mess-nav nav a{text-decoration:none}.mess-cover{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:30px;padding:30px 5% 70px;align-items:center}.mess-label{grid-column:1/-1;font-size:9px;letter-spacing:.15em;text-align:center;margin-bottom:12px}.mess-title>span{font:italic 19px 'Caveat', Georgia,serif;color:#9d4569;display:block;transform:rotate(-5deg);margin-left:8px}.mess-title h1{font:normal clamp(40px,5.2vw,72px)/1.02 'Caveat', Georgia,serif;letter-spacing:-.055em;margin:27px 0}.mess-title h1 em{color:#9d4569}.mess-title p{font-size:13px;line-height:1.8;max-width:330px}.mess-link{display:inline-block;background:#e8d69e;padding:16px 20px;font-size:10px;letter-spacing:.06em;text-decoration:none;border:1px dashed #48404a;outline:5px solid #e8d69e;margin:22px 5px 0;transform:rotate(-2deg);transition:transform .2s}.mess-link:hover{transform:rotate(2deg)}.mess-art{position:relative;transform:rotate(3deg);padding:12px;background:#fff;border:1px solid #d2c9b9;box-shadow:5px 6px 0 #d8cdb880}.mess-art::before{content:"";position:absolute;left:39%;top:-15px;width:110px;height:32px;background:#c5d7acaa;transform:rotate(-5deg);z-index:1}.mess-art-note{position:absolute;right:-10px;bottom:-25px;padding:18px 27px;background:#f2d3db;transform:rotate(-10deg);font:20px/1.05 'Caveat', Georgia,serif;box-shadow:3px 3px 0 #c9a6b4}.mess-doodle{position:absolute;left:43%;bottom:18px;font-size:75px;color:#9d4569;transform:rotate(15deg)}.mess-make{padding:35px 5% 50px;border-top:1px dashed #b9aa90;border-bottom:1px dashed #b9aa90;background:#efe9f0}.mess-section-top{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:28px}.mess-section-top h2{font:normal 35px 'Caveat', Georgia,serif;letter-spacing:-1px}.mess-section-top>span{font:italic 15px 'Caveat', Georgia,serif;color:#9d4569}.mess-projects{display:grid;grid-template-columns:repeat(3,1fr);gap:27px}.mess-projects a{position:relative;background:#e1e9cd;padding:33px 24px 27px;transform:rotate(-1.5deg);border:1px dashed #9ca781;box-shadow:4px 4px 0 #c5bea8;text-decoration:none;transition:transform .2s}.mess-projects a:hover{transform:rotate(1deg) translateY(-5px)}.mess-projects a:nth-child(2){background:#f2d3db;transform:rotate(1.5deg);border-color:#c39fac}.mess-projects a:nth-child(3){background:#e8d69e;border-color:#b9a974}.mess-tab{font-size:8px;letter-spacing:.08em;position:absolute;top:-12px;left:15px;background:#faf6e9;padding:8px 12px;border:1px solid #c7bdad}.mess-projects b{font:42px 'Caveat', Georgia,serif;color:#9d4569}.mess-projects h3{font:normal 28px 'Caveat', Georgia,serif;letter-spacing:-1px;margin:15px 0}.mess-projects p{font-size:12px;line-height:1.7}.mess-projects strong{font-size:9px;letter-spacing:.04em;display:block;margin-top:22px}.section-heading{font:normal 39px 'Caveat', Georgia,serif;text-align:center;letter-spacing:-1px;margin:50px 20px 30px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;padding:0 5% 55px}.post-card{padding:14px;background:#fffef9;border:1px solid #d2c9b9;box-shadow:3px 4px 0 #d8cdb870}.post-card:nth-child(2){transform:rotate(1deg)}.post-media{aspect-ratio:1.25;background:#e6d3df;border:1px solid #d2c9b9;margin-bottom:18px}.post-meta{font-size:9px;color:#9d4569}.post-title{font:normal 25px/1.15 'Caveat', Georgia,serif;letter-spacing:-.5px}.post-excerpt{font-size:12px}.mess-note{position:relative;margin:10px auto 65px;max-width:710px;text-align:center;padding:43px 25px;background:repeating-linear-gradient(#fff9db 0 29px,#d8d1b0 29px 30px);border:1px solid #d8d1b0;transform:rotate(-1deg);box-shadow:6px 7px 0 #d8cdb870}.mess-tape{position:absolute;width:115px;height:30px;background:#bbd0e6bb;left:calc(50% - 57px);top:-15px;transform:rotate(7deg)}.mess-note-label{font-size:9px;letter-spacing:.13em}.mess-note h2{font:italic normal 37px/1.1 'Caveat', Georgia,serif;color:#9d4569;letter-spacing:-1px;margin:26px 0}.mess-note p{font-size:13px;line-height:30px}.mess-signature{font:italic 21px 'Caveat', Georgia,serif;color:#9d4569;display:block;margin-top:23px}.mess-footer{display:flex;justify-content:space-between;gap:25px;align-items:center;border-top:1px dashed #b9aa90;padding:30px 5%}.mess-footer strong{font:italic bold 23px 'Caveat', Georgia,serif}.mess-footer span{font-size:10px;line-height:1.7}.mess-footer a{font-size:9px;font-weight:bold}@media(max-width:700px){.mess-nav .brand{font-size:19px}.mess-nav nav{font-size:9px;gap:10px}.mess-nav .brand span{display:none}.mess-cover{grid-template-columns:1fr;padding-top:22px}.mess-title h1{font-size:54px}.mess-art{margin:20px 12px}.mess-doodle{left:auto;right:10px;bottom:7px;font-size:55px}.mess-section-top{display:block}.mess-section-top h2{font-size:30px}.mess-projects,.posts-grid{grid-template-columns:1fr;gap:33px}.mess-note{margin:5px 6% 50px;padding:40px 15px}.mess-note h2{font-size:28px}.mess-footer{flex-wrap:wrap}} .latest{max-width:none;margin:0;padding:0}
@media(max-width:700px){.mess-doodle{right:16px}}
h1,h2,h3{font-family:'Caveat', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
